import path from "node:path";
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";

// Originally generated by Emergent; its preview-only plugins (visual edits, error overlay,
// polling file watcher) were removed so the app builds anywhere.
// https://vite.dev/config/
export default defineConfig({
  plugins: [react(), tailwindcss()],
  resolve: {
    alias: [
      { find: "@", replacement: path.resolve(__dirname, "./src") },
      // lucide 1.x dropped brand logos; src/lib/lucide-react.tsx restores them on top of the real package.
      { find: /^lucide-react$/, replacement: path.resolve(__dirname, "./src/lib/lucide-react.tsx") },
      { find: "lucide-react-upstream", replacement: path.resolve(__dirname, "./node_modules/lucide-react") },
      // recharts 3's Tooltip callback types are strict; src/lib/recharts.tsx adapts them.
      { find: /^recharts$/, replacement: path.resolve(__dirname, "./src/lib/recharts.tsx") },
      { find: "recharts-upstream", replacement: path.resolve(__dirname, "./node_modules/recharts") },
    ],
  },
  server: {
    host: true,
    port: 3000,
    // The frontend always calls relative /api/*; in dev Vite proxies it to FastAPI.
    proxy: {
      "/api": { target: process.env.API_PROXY_TARGET ?? "http://localhost:8001", changeOrigin: true },
    },
  },
});
